INSERT INTO public.notes (id, slug, title, summary, content, status, published_at, created_at, updated_at, view_count) VALUES (E'e4de62c5-546d-481d-952f-70f1fa2aa1d9', E'hello-heiqiao-notes', E'你好，黑巧笔记', E'这是我的个人站点，一个用来记录想法、项目和日常的安静角落。', E'# 你好，黑巧笔记\n\n欢迎来到这里。这是**黑巧笔记**，我的个人网站。\n\n它不是博客模板的直接展示，而是一次完整的"从脚手架到自己的地方"的建造过程。\n\n## 这里会放什么\n\n- **笔记**：技术探索、踩坑记录、读书随笔，长短不拘\n- **项目**：从想法变成现实的小东西\n- **关于**：一点点自我介绍\n\n## 为什么叫"数字花园"\n\n我喜欢这个比喻：笔记不是写完就封存的"文章"，而是可以不断生长的东西。今天写一个粗略的想法，过几个月再回来补充、修正、重新链接——它像植物一样慢慢长成自己的样子。\n\n> 写下来，才算想过。\n\n## 技术上的小事\n\n这个站点的前端基于 React + Vite，后端是 Fastify + PostgreSQL，编辑器用了 ByteMD。没有用任何现成的博客系统，所有代码都是自己搭起来的——这正是它有意思的地方。\n\n慢慢写，慢慢长。', E'published', E'2026-11-26T07:56:49.546Z', E'2026-11-26T07:56:49.546Z', E'2026-11-26T09:15:30.702Z', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notes (id, slug, title, summary, content, status, published_at, created_at, updated_at, view_count) VALUES (E'53c17177-1838-4ed2-93d4-699f052e123a', E'fullstack-template-to-blog', E'从全栈脚手架到个人博客', E'记录这套系统从通用模板演变成个人站的过程，以及中间做的几个关键取舍。', E'# 从全栈脚手架到个人博客\n\n这个站点的起点是一个通用的前后端分离脚手架。这篇文章记录它"改造"的过程和几个关键决策。\n\n## 起点：两套独立的模板\n\n最初我把脚手架拆成两个完全独立的项目：\n\n- `fullstack-frontend`：Vite 5 + React 18 + TypeScript + Ant Design\n- `fullstack-backend`：Node 22 + Fastify 5 + Drizzle ORM + PostgreSQL\n\n两者各自有独立的仓库、依赖和测试，谁也不依赖谁。这样做的好处是：以后任何新项目都可以从模板复制一份，干净起步。\n\n## 关键取舍\n\n### 1. 契约各持一份\n\n原本前后端共享一个 `@template/shared` 包。为了让两个项目真正独立，我让**前后端各持一份类型定义**（`contract.ts`）。代价是改契约要同步两边，换来的是物理上的彻底解耦。\n\n### 2. 注册改成邀请制\n\n个人站只有一个作者，所以直接关闭了公开注册。作者账号由命令行脚本创建：\n\n```bash\npnpm create-admin <email> <name> <password>\n```\n\n后端 `requireAdmin` 守卫是唯一安全边界，前端的界面隐藏只是体验层。\n\n### 3. 数据操作全部下沉到接口\n\n文章管理的搜索、筛选、排序、分页——最开始是在前端本地做的（一次拉 100 条再过滤）。后来全部改成 SQL 层实现：\n\n```\nGET /api/v1/admin/notes?status=draft&keyword=xx&sortBy=title&sortOrder=asc&page=1&pageSize=10\n```\n\n这样数据量大起来也不会卡。\n\n## 写在最后\n\n脚手架的价值不在于代码本身，而在于它把"从零到能跑"的时间压缩了。剩下的，就是往里面填属于自己的东西。', E'published', E'2026-11-26T07:56:49.585Z', E'2026-11-26T07:56:49.585Z', E'2026-11-26T07:56:49.585Z', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notes (id, slug, title, summary, content, status, published_at, created_at, updated_at, view_count) VALUES (E'e65c225b-2d93-4aa0-8775-0e41692b9f08', E'why-build-my-own-blog', E'为什么我要自己做一个博客', E'在平台写作很方便，但拥有一个完全属于自己的地方，感觉不一样。', E'# 为什么我要自己做一个博客\n\n自媒体平台很好用，但总有种"租来的房子"的感觉。自己搭一个站，是从"租客"变成"房东"。\n\n## 三个理由\n\n### 1. 数据在自己手里\n\n文章、图片、访问记录都放在自己的数据库里。想导出就导出，想改结构就改结构，不用看平台的脸色。\n\n### 2. 可以自由地丑，也可以自由地美\n\n模板有模板的规矩。自己的站，今天想极简就极简，明天想加个奇怪的小组件就加。这种自由本身就很值钱。\n\n### 3. 造东西的过程本身就是收获\n\n从配置数据库、写接口，到调编辑器、做页面，每一步都在加深对整个 Web 技术栈的理解。 blog 只是结果，造它的过程才是目的。\n\n## 但也要诚实\n\n自建站点要处理的事比想象中多：安全、备份、部署、SEO……如果只是想安静写东西，用现成平台可能更明智。\n\n对我来说，折腾本身也是乐趣的一部分。', E'published', E'2026-11-26T07:56:49.619Z', E'2026-11-26T07:56:49.619Z', E'2026-11-26T07:56:49.619Z', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notes (id, slug, title, summary, content, status, published_at, created_at, updated_at, view_count) VALUES (E'27be052c-9407-40fc-8a37-a02c18f251cb', E'writing-with-bytemd', E'用 ByteMD 写作的体验', E'把编辑器从裸 textarea 换成 ByteMD 之后，写作这件事变得舒服多了。', E'# 用 ByteMD 写作的体验\n\n编辑器是博客的"工作台"。一个好用的编辑器，能让人更愿意坐下来写点东西。\n\n## 之前：裸 textarea\n\n最开始的编辑器就是一个简单的文本框，配一个实时预览。能用，但：\n\n- 格式要自己手打 Markdown 符号\n- 图片要手动上传再复制链接\n- 代码块、表格这些写起来很累\n\n## 现在：ByteMD\n\n换成 ByteMD 之后，这些痛点都解决了：\n\n- **工具栏**：标题、加粗、列表、引用、代码块，一键插入\n- **GFM 支持**：表格、任务列表、删除线\n- **数学公式**：KaTeX 渲染，行内和块级都支持\n- **代码高亮**：多种语言自动识别\n- **图片上传**：粘贴截图、拖拽文件，自动传到服务器并插入\n\n## 图片上传的实现\n\n后端加了一个上传接口，图片存到本地 `uploads/` 目录：\n\n```ts\napp.post(''/upload'', { onRequest: [requireAdmin] }, async (req) => {\n  const data = await req.file();\n  // 校验类型、大小，写入磁盘，返回 /uploads/xxx.png\n  return { url: `/uploads/${filename}` };\n});\n```\n\n前端的 ByteMD 通过 `uploadImages` 回调接管粘贴和拖拽事件。写文章时贴一张图，所见即所得。\n\n## 一个小教训\n\n编辑器插入图片时，**一定要存相对路径**（`/uploads/xxx.png`），不要存绝对 URL。否则换域名、换部署环境的时候，所有图片都会失效。', E'published', E'2026-11-26T07:56:49.654Z', E'2026-11-26T07:56:49.654Z', E'2026-11-26T07:56:49.654Z', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notes (id, slug, title, summary, content, status, published_at, created_at, updated_at, view_count) VALUES (E'342f78ad-ee0e-47c6-82e5-6bbfbb8513b9', E'digital-garden-notes', E'数字花园：让笔记慢慢生长', E'一种关于笔记的思维方式：不追求写完，而追求 continually 生长。', E'# 数字花园：让笔记慢慢生长\n\n传统博客的文章是"完成时"——写完、发布、封存。数字花园里的笔记是"进行时"——随时可以回来修改、补充、重新组织。\n\n## 两种心态\n\n| 博客文章 | 数字花园 |\n|---|---|\n| 写完发布 | 随时更新 |\n| 按时间排列 | 按主题生长 |\n| 读者消费内容 | 作者也在整理思路 |\n| 越积越旧 | 越养越丰满 |\n\n## 我打算怎么做\n\n这个站点的笔记，我会允许自己"写得粗糙"：\n\n- 想到什么先记下来，不用等到想清楚\n- 过一段时间回来补充，把零散的想法连起来\n- 标题和标签可以随时调整，不追求一次到位\n\n## 一个小例子\n\n这篇笔记本身就是一个开始。以后如果我读到了关于数字花园的新想法，会直接回来补充这里，而不是再写一篇新的"续集"。\n\n> 重要的不是每篇笔记有多完美，而是它们能慢慢长成一片花园。\n\n慢慢写，慢慢长。', E'published', E'2026-11-26T07:56:49.688Z', E'2026-11-26T07:56:49.688Z', E'2026-11-26T07:56:49.688Z', 0) ON CONFLICT (id) DO NOTHING;
